from __future__ import annotations

import argparse
import tomllib
from pathlib import Path

ROOT = Path(__file__).parents[1]
SOURCE = ROOT / "config" / "retry-policy.toml"
TARGET = ROOT / "src" / "retries" / "generated_policy.py"
DEFAULT_ATTEMPTS = 3


def render() -> str:
    raw = tomllib.loads(SOURCE.read_text(encoding="utf-8"))
    attempts = raw.get("channels", {}).get("email", {}).get(
        "max_attempts", DEFAULT_ATTEMPTS
    )
    return (
        "# Generated by tools/render_policy.py; do not edit.\n"
        f"MAX_ATTEMPTS = {{'email': {attempts}}}\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    rendered = render()
    if args.check:
        return 0 if TARGET.read_text(encoding="utf-8") == rendered else 1
    TARGET.write_text(rendered, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
